"""Offline versioned map agent and causal replay.

Published images are immutable. All rejection checks precede mutation; reference
counts cover exactly contexts, packets, and current files, not active pointers.
"""
import re
import struct
from dataclasses import dataclass, field
from .create_dfa import create, DENY
from syntax import PolicyError, parse

OK = {'ok': True}
REJECTED = {'error': 'rejected'}
_HEX = re.compile(r'[0-9a-fA-F]{48}\Z')


@dataclass(slots=True)
class Image:
    data: dict
    cells: int
    refs: int = 0


@dataclass(slots=True)
class Unit:
    identity: tuple
    service: str
    mark: int = 0
    contexts: dict = field(default_factory=dict)


@dataclass(slots=True)
class Packet:
    context: tuple
    destination: str
    wire: str
    receipt: object = None


@dataclass(slots=True)
class Connection:
    generation: int
    mark: int = 0
    packets: dict = field(default_factory=dict)


class Agent:
    def __init__(self, services, limits):
        self.services = services
        ordered = sorted(services, key=lambda s: s['label'])
        self.columns = {s['name']: i for i, s in enumerate(ordered)}
        self.labels = {s['name']: s['label'] for s in services}
        self.limits = limits
        self.images = {}
        self.active = None
        self.epoch_mark = 0
        self.cells = self.contexts = self.packets = 0
        self.units = {}
        self.unit_marks = {}
        self.connections = {}
        self.connection_marks = {}
        self.files = {}
        self.file_marks = {}

    def unit(self, identity):
        u = self.units.get(tuple(identity[:2]))
        return u if u is not None and u.identity[2] == identity[2] else None

    def connection(self, identity):
        c = self.connections.get(identity[0])
        return c if c is not None and c.generation == identity[1] else None

    def source(self, event):
        unit = self.unit(event['unit'])
        return unit.contexts.get(event['rid']) if unit is not None else None

    def ref(self, context, delta):
        self.images[context[0]].refs += delta

    def advance(self, context, service):
        epoch, state = context
        if state != DENY:
            state = self.images[epoch].data['rows'][state][self.columns[service]]
        return epoch, state

    def new_request(self, unit, rid):
        return unit is not None and rid > unit.mark and self.contexts < self.limits['contexts']

    def insert_context(self, unit, rid, context):
        unit.contexts[rid] = context
        unit.mark = rid
        self.contexts += 1
        self.ref(context, 1)
        return {'ok': True, 'epoch': context[0], 'state': context[1]}

    def can_spawn(self, identity):
        pair = tuple(identity[:2])
        return (pair not in self.units and
                identity[2] > self.unit_marks.get(pair, 0) and
                len(self.units) < self.limits['units'])

    def event(self, event, policy=None):
        op = event['op']
        if op == 'stage':
            epoch = event['epoch']
            if epoch <= self.epoch_mark or len(self.images) >= self.limits['images']:
                return REJECTED
            try:
                if policy is None:
                    policy = parse(event['policy'])
                image = create(policy, self.services)
            except PolicyError:
                return REJECTED
            cells = sum(target != DENY for row in image['rows'] for target in row)
            if self.cells + cells > self.limits['cells']:
                return REJECTED
            # Only now publish the entire staged image, never a partially loaded map.
            self.images[epoch] = Image(image, cells)
            self.cells += cells
            self.epoch_mark = epoch
            return {'ok': True, 'epoch': epoch, 'image': image}
        if op == 'commit':
            epoch = event['epoch']
            if epoch not in self.images:
                return REJECTED
            self.active = epoch
            return OK
        if op == 'retire':
            epoch = event['epoch']
            image = self.images.get(epoch)
            if image is None or epoch == self.active or image.refs:
                return REJECTED
            self.cells -= image.cells
            del self.images[epoch]
            return OK
        if op == 'spawn':
            identity, service = event['unit'], event['service']
            if service not in self.columns or not self.can_spawn(identity):
                return REJECTED
            pair = tuple(identity[:2])
            self.units[pair] = Unit(tuple(identity), service)
            self.unit_marks[pair] = identity[2]
            return OK
        if op == 'clone':
            parent = self.unit(event['parent'])
            identity = event['child']
            if (parent is None or not self.can_spawn(identity) or
                    self.contexts + len(parent.contexts) > self.limits['contexts']):
                return REJECTED
            child = Unit(tuple(identity), parent.service, parent.mark, parent.contexts.copy())
            pair = tuple(identity[:2])
            self.units[pair] = child
            self.unit_marks[pair] = identity[2]
            self.contexts += len(child.contexts)
            for context in child.contexts.values():
                self.ref(context, 1)
            return OK
        if op == 'exit':
            unit = self.unit(event['unit'])
            if unit is None:
                return REJECTED
            for context in unit.contexts.values():
                self.ref(context, -1)
            self.contexts -= len(unit.contexts)
            del self.units[unit.identity[:2]]
            return OK
        if op == 'begin':
            unit, rid = self.unit(event['unit']), event['rid']
            if self.active is None or not self.new_request(unit, rid):
                return REJECTED
            return self.insert_context(unit, rid, self.advance((self.active, 0), unit.service))
        if op == 'finish':
            unit, rid = self.unit(event['unit']), event['rid']
            if unit is None or rid not in unit.contexts:
                return REJECTED
            context = unit.contexts.pop(rid)
            epoch, state = context
            allow = state != DENY and self.images[epoch].data['accept'][state]
            self.ref(context, -1)
            self.contexts -= 1
            return {'ok': True, 'allow': allow}
        if op == 'open':
            cid, generation = event['connection']
            if (cid in self.connections or generation <= self.connection_marks.get(cid, 0) or
                    len(self.connections) >= self.limits['connections']):
                return REJECTED
            self.connections[cid] = Connection(generation)
            self.connection_marks[cid] = generation
            return OK
        if op == 'send':
            context = self.source(event)
            conn = self.connection(event['connection'])
            stream, destination = event['stream'], event['destination']
            if (context is None or conn is None or destination not in self.labels or
                    stream <= conn.mark or self.packets >= self.limits['packets']):
                return REJECTED
            wire = struct.pack('!4sIIIII', b'EMC4', context[0], context[1],
                               self.labels[destination], stream, conn.generation).hex()
            conn.packets[stream] = Packet(context, destination, wire)
            conn.mark = stream
            self.packets += 1
            self.ref(context, 1)
            return {'ok': True, 'wire': wire}
        if op == 'recv':
            conn = self.connection(event['connection'])
            packet = conn.packets.get(event['stream']) if conn is not None else None
            unit, rid = self.unit(event['unit']), event['rid']
            if packet is None or unit is None or unit.service != packet.destination:
                return REJECTED
            wire = event['wire']
            if wire is not None and (_HEX.fullmatch(wire) is None or wire.lower() != packet.wire):
                return REJECTED
            receipt = (unit.identity, rid)
            if packet.receipt is not None:
                if packet.receipt != receipt or rid not in unit.contexts:
                    return REJECTED
                epoch, state = unit.contexts[rid]
                return {'ok': True, 'epoch': epoch, 'state': state}
            if not self.new_request(unit, rid):
                return REJECTED
            context = self.advance(packet.context, unit.service)
            packet.receipt = receipt
            return self.insert_context(unit, rid, context)
        if op == 'close':
            conn = self.connection(event['connection'])
            if conn is None:
                return REJECTED
            for packet in conn.packets.values():
                self.ref(packet.context, -1)
            self.packets -= len(conn.packets)
            del self.connections[event['connection'][0]]
            return OK
        if op == 'store':
            context = self.source(event)
            fid, generation = event['file']
            old = self.files.get(fid)
            if context is None:
                return REJECTED
            if old is None:
                if (generation <= self.file_marks.get(fid, 0) or
                        len(self.files) >= self.limits['files']):
                    return REJECTED
            elif old[0] != generation:
                return REJECTED
            # An overwrite consumes no new file slot and may replace an old epoch.
            if old is not None:
                self.ref(old[1], -1)
            self.files[fid] = (generation, context)
            self.file_marks[fid] = generation
            self.ref(context, 1)
            return OK
        if op == 'load':
            fid, generation = event['file']
            saved = self.files.get(fid)
            unit, rid = self.unit(event['unit']), event['rid']
            if saved is None or saved[0] != generation or not self.new_request(unit, rid):
                return REJECTED
            return self.insert_context(unit, rid, self.advance(saved[1], unit.service))
        if op == 'unlink':
            fid, generation = event['file']
            saved = self.files.get(fid)
            if saved is None or saved[0] != generation:
                return REJECTED
            self.ref(saved[1], -1)
            del self.files[fid]
            return OK
        if op == 'inspect':
            return {'ok': True, 'active': self.active,
                    'images': [[epoch, len(image.data['rows']), image.cells, image.refs]
                               for epoch, image in sorted(self.images.items())],
                    'units': len(self.units), 'contexts': self.contexts,
                    'connections': len(self.connections), 'packets': self.packets,
                    'files': len(self.files)}
        raise AssertionError('validated operation')
PY
